parameters.jsCode:
const binaryBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
return [{
  json: {
    ...$input.first().json,
    pdfBase64: binaryBuffer.toString('base64')
  }
}];

// 1. بيانات العميل والطلب من Webhook
const rawWebhook = $('Webhook1').first()?.json?.body?.data || {};
const webhookProps = rawWebhook.properties || rawWebhook;

// دالة مرنة لاستخراج القيمة مهما كان نوع الحقل بـ Notion
function extractAny(val) {
  if (!val && val !== 0) return '';
  if (typeof val === 'string' || typeof val === 'number') return String(val);
  if (Array.isArray(val)) {
    if (val.length === 0) return '';
    return val.map(v => extractAny(v)).join('');
  }
  if (typeof val === 'object') {
    if (val.plain_text) return val.plain_text;
    if (val.text?.content) return val.text.content;
    if (val.url) return val.url;
    if (val.email) return val.email;
    if (val.phone_number) return val.phone_number;
    if (val.name) return val.name;
    if (val.title) return extractAny(val.title);
    if (val.rich_text) return extractAny(val.rich_text);
    if (val.file?.url) return val.file.url;
    if (val.external?.url) return val.external.url;
    if (val.files) return extractAny(val.files);
  }
  return '';
}

// استخراج بيانات العميل والماليات
const clientName = extractAny(webhookProps['Client Name']) || '';
let clientEmail = extractAny(webhookProps['Client Email']) || '';

// معالجة البريد الإلكتروني لمنع خطأ Resend (استبدال الإيميلات الوهمية أو الفارغة)
if (!clientEmail || clientEmail.includes('example.com')) {
  clientEmail = 'salehalzohery@gmail.com'; // اكتب إيميلك الحقيقي هنا للاختبار
}

const rawAmount = $('Get Quote Data1').first().json.property_amount_details || '0';
const rawDiscount = (parseFloat($('Get Quote Data1').first().json.property_discount) * 100) || 0;

// 2. قراءة بيانات الشركة من Get Company Settings
let companyName = "اسم الشركة";
let companyLogo = "";
let primaryColor = "#2c3e50";
let companyEmail = "";
let companyPhone = "";

try {
  const nodeData = $('Get Company Settings1').first()?.json || {};    
  const props = nodeData.properties || nodeData;

  const getFlexProp = (keyName) => {
    if (!props) return '';
    const key = Object.keys(props).find(k => k.trim().toLowerCase() === keyName.trim().toLowerCase());
    return key ? extractAny(props[key]) : '';
  };

  companyName = getFlexProp('property_company_name') || companyName;
  companyLogo = getFlexProp('property_company_logo_url') || companyLogo;
  primaryColor = getFlexProp('property_primary_color') || primaryColor;
  companyEmail = getFlexProp('property_company_email') || companyEmail;
  companyPhone = getFlexProp('property_company_phone') || companyPhone;
} catch (e) {}

// 3. الحسابات والرياضيات
const subtotal = parseFloat(String(rawAmount).replace(/[^0-9.]/g, '')) || 0;
let discountPercent = parseFloat(String(rawDiscount).replace(/[^0-9.]/g, '')) || 0;

if (discountPercent > 0 && discountPercent < 1) {
  discountPercent = discountPercent * 100;
}

const invoiceNumber = `INV-${Date.now().toString().slice(-6)}`;
const invoiceDate = new Date().toLocaleDateString('ar-SA', { year: 'numeric', month: 'long', day: 'numeric' });

const discountAmount = subtotal * (discountPercent / 100);
const afterDiscount = subtotal - discountAmount;
const vat = afterDiscount * 0.15;
const total = afterDiscount + vat;

// 4. هيكل HTML الهجين للـ PDF
const htmlContent = `<!DOCTYPE html>
<html dir="rtl" lang="ar">
<head>
  <meta charset="UTF-8">
  <style>
    body { font-family: Arial, sans-serif; direction: rtl; text-align: right; color: #333; margin: 0; padding: 20px; }
    .header-table, .info-table, .data-table { width: 100%; border-collapse: collapse; margin-bottom: 20px; }
    .header-table td { vertical-align: middle; }
    .info-table { background-color: #f8f9fa; border-radius: 6px; }
    .info-table td { padding: 12px; vertical-align: top; width: 50%; }
    .data-table th, .data-table td { border: 1px solid #e0e0e0; padding: 10px; text-align: right; }
    .data-table th { background-color: ${primaryColor}; color: #ffffff; font-weight: bold; }
    .text-left { text-align: left !important; }
    .total-row { background-color: #f1f1f1; font-weight: bold; font-size: 15px; }
  </style>
</head>
<body>

  <!-- الهيدر واللوجو -->
  <table class="header-table" style="border-bottom: 3px solid ${primaryColor}; padding-bottom: 12px;">
    <tr>
      <td style="width: 50%;">
        ${companyLogo ? `<img src="${companyLogo}" style="max-height: 70px; max-width: 220px;" />` : `<h2 style="color: ${primaryColor}; margin:0;">${companyName}</h2>`}
      </td>
      <td class="text-left" style="width: 50%;">
        <h3 style="color: ${primaryColor}; margin: 0 0 5px 0;">عرض سعر / فاتورة</h3>
        <div style="font-size: 13px; color: #555;">رقم الفاتورة: <b>${invoiceNumber}</b></div>
        <div style="font-size: 13px; color: #555;">التاريخ: ${invoiceDate}</div>
      </td>
    </tr>
  </table>

  <!-- بيانات الطرفين -->
  <table class="info-table">
    <tr>
      <td>
        <strong style="color: ${primaryColor}; display: block; margin-bottom: 5px;">صادرة من:</strong>
        <div style="font-size: 14px; margin-bottom: 3px;"><b>${companyName}</b></div>
        ${companyEmail ? `<div style="font-size: 13px; color: #555;">البريد: ${companyEmail}</div>` : ''}
        ${companyPhone ? `<div style="font-size: 13px; color: #555;">الهاتف: ${companyPhone}</div>` : ''}
      </td>
      <td class="text-left">
        <strong style="color: ${primaryColor}; display: block; margin-bottom: 5px;">موجهة إلى:</strong>
        <div style="font-size: 14px; margin-bottom: 3px;"><b>${clientName}</b></div>
        ${clientEmail ? `<div style="font-size: 13px; color: #555;">${clientEmail}</div>` : ''}
      </td>
    </tr>
  </table>

  <!-- الجدول المالي -->
  <table class="data-table">
    <thead>
      <tr>
        <th>البند</th>
        <th class="text-left">المبلغ (ر.س)</th>
      </tr>
    </thead>
    <tbody>
      <tr>
        <td>المبلغ الأساسي</td>
        <td class="text-left">${subtotal.toFixed(2)}</td>
      </tr>
      ${discountPercent > 0 ? `
      <tr style="color: #c0392b;">
        <td>الخصم (${discountPercent}%)</td>
        <td class="text-left">-${discountAmount.toFixed(2)}</td>
      </tr>
      ` : ''}
      <tr>
        <td>ضريبة القيمة المضافة (15%)</td>
        <td class="text-left">${vat.toFixed(2)}</td>
      </tr>
      <tr class="total-row">
        <td style="color: ${primaryColor};">الإجمالي النهائي</td>
        <td class="text-left" style="color: ${primaryColor};">${total.toFixed(2)}</td>
      </tr>
    </tbody>
  </table>

</body>
</html>`;

// 5. تحويل الـ HTML وتنظيف سلسلة Base64 نهائياً من أي مسافات أو أسطر جديدة
const htmlBase64 = Buffer.from(htmlContent, 'utf-8')
  .toString('base64')
  .replace(/[\r\n\s]+/g, '');

return [
  {
    json: {
      html: htmlContent,
      htmlBase64: htmlBase64,
      clientEmail: clientEmail,
      clientName: clientName
    }
  }
];
